import random
import unittest
from bptree import BPlusTree

class TestBPlusTree(unittest.TestCase):
    def test_randomized_insert_delete_range_oracle(self):
        rng = random.Random(2026)
        tree = BPlusTree(order=4)
        ref = {}
        for step in range(600):
            op = rng.random()
            k = rng.randint(0, 80)
            if op < 0.55:
                v = f'v{step}'
                tree.insert(k, v)
                ref[k] = v
            elif op < 0.90:
                got = tree.delete(k)
                exp = k in ref
                ref.pop(k, None)
                self.assertEqual(got, exp, f'delete({k}) mismatch at step {step}')
            else:
                lo = rng.randint(0, 60)
                hi = lo + rng.randint(0, 25)
                exp_r = sorted((kk, vv) for kk, vv in ref.items() if lo <= kk <= hi)
                self.assertEqual(tree.range_query(lo, hi), exp_r)
        for k in range(85):
            self.assertEqual(tree.get(k), ref.get(k))

if __name__ == '__main__':
    unittest.main()

