import heapq

def route_demands(edges: list[dict], demands: list[dict]) -> list[dict[str, float]]:
    # Naive all-or-nothing shortest path by free-flow t0 (causes massive BPR^4 congestion)
    adj = {}
    for e in edges:
        adj.setdefault(e['u'], []).append(e)
    out = []
    for d in demands:
        dist = {d['src']: 0.0}; prev = {}; pq = [(0.0, d['src'])]
        while pq:
            cost, u = heapq.heappop(pq)
            if u == d['dst']: break
            if cost > dist.get(u, 1e18): continue
            for e in adj.get(u, []):
                nc = cost + e['t0']
                if nc < dist.get(e['v'], 1e18):
                    dist[e['v']] = nc; prev[e['v']] = e; heapq.heappush(pq, (nc, e['v']))
        flow = {}; cur = d['dst']
        while cur != d['src']:
            e = prev[cur]; flow[e['id']] = d['volume']; cur = e['u']
        out.append(flow)
    return out

